<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import AssetWorkspace from '../../../src/features/assets/components/AssetWorkspace.vue';
import QueryPanel from '../../../src/features/assets/components/QueryPanel.vue';
import AssetOwnershipGate from '../../../src/features/assets/components/AssetOwnershipGate.vue';
import AssetRuleSettings from '../../../src/features/assets/components/AssetRuleSettings.vue';
import ExposureSurface from '../../../src/features/assets/exposure/ExposureSurface.vue';
import CollectionRunSummary from '../../../src/features/assets/components/CollectionRunSummary.vue';
import ConfigurationProfiles from './ConfigurationProfiles.vue';
import {assetApi} from '../../../src/features/assets/api';
import type {Project} from '../../../src/features/workspaces/types';
import type {AssetEvent,AssetExecutionProfile,JobRun,LogEntry,ScopedReprobeRequest} from '../../../src/features/assets/types';
import {bindAssetsClient,clearAssetsClient,invoke,subscribeAssetsArtifacts,downloadAssetsArtifact,subscribeAssetsUpload,checkAssetsUpload,continueAssetsUpload,discardAssetsUpload} from './ports/client.mjs';
import {cancelAssetDialog,assetConfirm} from './ports/dialogs.mjs';
import {useI18n} from './ports/i18n';
import {initializeAssetPreferences,clearAssetPreferences,subscribeAssetPreferences,reloadAssetPreferences} from './ports/storage.mjs';
const props=defineProps<{client:any}>();
const {locale,tr,setLocale}=useI18n();
const context=ref<{hostProjectId:number;nativeProjectId:number;name:string;status:string}>();
const profiles=ref<AssetExecutionProfile[]>([]),view=ref('assets'),notice=ref(''),noticeKind=ref('info'),error=ref('');
const runs=ref<JobRun[]>([]),logs=ref<LogEntry[]>([]),events=ref<AssetEvent[]>([]),loading=ref(false),loaded=ref(false),busy=ref(new Set<number>());
const preferenceState=ref<any>({state:'unloaded',unsaved:false,errorCode:''}),preferenceMount=ref(0);
const unsubscribePreferences=subscribeAssetPreferences((value:any)=>{preferenceState.value=value;});
const navigationState=ref({loading:false,externalOpen:false,handoff:false,error:false});
const upload=ref<any>(null),uploadBusy=ref(false);
const unsubscribeUpload=subscribeAssetsUpload((value:any)=>{upload.value=value;});
let navigationGeneration=0,unsubscribeNavigation:(()=>void)|undefined;
const artifacts=ref<any[]>([]);const unsubscribeArtifacts=subscribeAssetsArtifacts((items:any[])=>{artifacts.value=items;});
let disposed=false,generation=0,contextGeneration=0,timer:ReturnType<typeof setInterval>;
const project=computed(()=>context.value?({id:context.value.nativeProjectId,name:context.value.name,status:context.value.status} as Project):undefined);
const projects=computed(()=>project.value?[project.value]:[]);
const tabs=computed(()=>[['assets',tr('资产库存','Assets')],['query',tr('采集目标','Collection')],['tasks',tr('任务','Tasks')],['changes',tr('资产变化','Changes')],['logs',tr('日志','Logs')],['rules',tr('隔离规则','Rules')],['ownership',tr('归属与授权','Ownership and authorization')],['exposure',tr('公开暴露面','Exposure')],['configuration',tr('执行配置','Configuration')]]);
const notify=(kind:string,text:string)=>{noticeKind.value=kind;notice.value=text;};
const currentProfile=()=>profiles.value.find(p=>p.isDefault)||profiles.value[0];
async function refreshProfiles(){const request=contextGeneration;try{const rows=await invoke('list_asset_job_profiles');if(!disposed&&request===contextGeneration&&Array.isArray(rows))profiles.value=rows.map(row=>({id:row.id,name:row.name,isDefault:row.isDefault,settings:{runProbe:row.runProbe,runRefine:row.runRefine}}));}catch(failure){notify('error',String(failure));}}
async function download(id:string){try{await downloadAssetsArtifact(id);notify('info',tr('已开始下载；最终保存结果由浏览器确认。','Download started; the browser confirms whether the file is saved.'));}catch(failure){notify('error',tr('导出文件仍保留；可重试取回，未重新执行导出。','The issued export is retained. Retry retrieval; export was not rerun.')+' '+String(failure));}}
async function refreshNavigation(){const request=++navigationGeneration,hostContext=props.client.context,scope=contextGeneration;navigationState.value={loading:true,externalOpen:false,handoff:false,error:false};try{if(typeof props.client.navigationCapabilities!=='function')throw Error('assets_navigation_unavailable');const value=await props.client.navigationCapabilities('org.oviraptor.scanning','home');if(disposed||scope!==contextGeneration||request!==navigationGeneration||props.client.context!==hostContext)return;if(!value||typeof value.externalOpen!=='boolean'||typeof value.handoff!=='boolean')throw Error('assets_navigation_invalid');navigationState.value={loading:false,externalOpen:value.externalOpen,handoff:value.handoff,error:false};}catch{if(!disposed&&scope===contextGeneration&&request===navigationGeneration)navigationState.value={loading:false,externalOpen:false,handoff:false,error:true};}}
async function uploadAction(action:'check'|'continue'|'discard'){if(uploadBusy.value)return;if(action!=='check'&&!await assetConfirm(action==='discard'?tr('仅丢弃仍在接收的临时上传，不撤销任何业务记录，继续？','Discard only a still-receiving upload. This does not undo business records. Continue?'):tr('仅继续本次已登记上传的缺失块，完成后提交一次原导入。继续？','Continue missing chunks of this registered upload and submit the original import once after completion. Continue?')))return;uploadBusy.value=true;try{if(action==='check')await checkAssetsUpload();else if(action==='continue'){await continueAssetsUpload();notify('info',tr('原导入已返回；请核对本项目暴露面记录。','The original import returned; review this project’s exposure records.'));}else await discardAssetsUpload();}catch(failure){notify('error',String(failure));}finally{uploadBusy.value=false;}}
async function initialize(){const requested=++contextGeneration;generation++;navigationGeneration++;navigationState.value={loading:false,externalOpen:false,handoff:false,error:false};clearAssetPreferences();clearAssetsClient();cancelAssetDialog();context.value=undefined;profiles.value=[];runs.value=[];logs.value=[];events.value=[];loaded.value=false;error.value='';try{await props.client.ready;const value=await props.client.callAction('assets_context',{});if(disposed||requested!==contextGeneration)return;bindAssetsClient(props.client,value);await initializeAssetPreferences((name:string,args:any)=>invoke(name,args));if(disposed||requested!==contextGeneration)return;context.value=value;void refreshNavigation();const rows=await invoke('list_asset_job_profiles');if(disposed||requested!==contextGeneration)return;if(!Array.isArray(rows)||rows.some(row=>!Number.isSafeInteger(row.id)||typeof row.name!=='string'||typeof row.isDefault!=='boolean'||typeof row.runProbe!=='boolean'||typeof row.runRefine!=='boolean'))throw Error('assets_job_profiles_invalid');profiles.value=rows.map(row=>({id:row.id,name:row.name,isDefault:row.isDefault,settings:{runProbe:row.runProbe,runRefine:row.runRefine}}));await refresh();}catch(failure){if(!disposed&&requested===contextGeneration)error.value=String(failure);}}
async function reloadPreferences(){if(!await assetConfirm(tr('重新读取已保存布局会丢弃本页未保存的布局更改，继续？','Reloading the saved layout discards unsaved layout changes in this page. Continue?')))return;try{await reloadAssetPreferences();preferenceMount.value++;}catch(failure){notify('error',String(failure));}}
async function refresh(){if(!context.value)return;const request=++generation,projectId=context.value.nativeProjectId,tab=view.value;loading.value=true;error.value='';try{if(tab==='tasks') {const value=await assetApi.listRuns(projectId,100);if(request===generation)runs.value=value;}else if(tab==='logs'){const value=await assetApi.listLogs(undefined,500,projectId);if(request===generation)logs.value=value;}else if(tab==='changes'){const value=await assetApi.listEvents(projectId,undefined,200);if(request===generation)events.value=value;}if(request===generation)loaded.value=true;}catch(failure){if(request===generation)error.value=String(failure);}finally{if(request===generation&&!disposed)loading.value=false;}}
async function runAction(run:JobRun,action:'resume'|'cancel'){if(busy.value.has(run.id))return;if(action==='resume'&&!['full','collect','reprobe'].includes(run.pipeline)){notify('error',tr('旧任务流程不受支持，保留原任务，请核对配置。','The saved pipeline is unsupported. The original task is retained.'));return;}busy.value.add(run.id);const scope=context.value?.nativeProjectId;try{if(action==='resume')await assetApi.resumeJob(run.id);else await assetApi.cancelJob(run.id);if(context.value?.nativeProjectId===scope){notify('info',action==='cancel'?tr('已请求取消，终态以任务回执为准。','Cancellation requested; wait for the task receipt.'):tr('已提交同一任务的恢复请求，未创建替代任务。','Resume requested for the same task; no replacement task was created.'));await refresh();}}catch(failure){notify('error',String(failure));}finally{busy.value.delete(run.id);}}
async function reprobe(request:ScopedReprobeRequest){const {projectId,scope}=request;const profile=currentProfile();if(!profile||projectId!==context.value?.nativeProjectId){notify('error',tr('请先核对本项目执行配置。','Review the current project execution profile first.'));return;}if(!await assetConfirm(tr(`按「${profile.name}」复测当前筛选或勾选的 ${scope.expectedCount} 条资产？不会启动新的来源采集。`,`Re-probe these ${scope.expectedCount} filtered or selected assets using ${profile.name}? No new provider collection is started.`)))return;if(projectId!==context.value?.nativeProjectId)return;try{await assetApi.startJob(projectId,profile.id,tr('资产复测','Asset re-probe'),'reprobe',undefined,scope);view.value='tasks';await refresh();}catch(failure){notify('error',String(failure));}}
watch(view,()=>{generation++;loaded.value=false;error.value='';void refresh();});
onMounted(()=>{if(typeof props.client.subscribeNavigation==='function')unsubscribeNavigation=props.client.subscribeNavigation(()=>{void refreshNavigation();});void initialize();timer=setInterval(()=>{if(disposed)return;if(context.value&&props.client.context?.projectId!==context.value.hostProjectId){void initialize();return;}if(view.value==='tasks'&&runs.value.some(run=>['queued','running','cancel_requested'].includes(run.status))&&!loading.value)void refresh();},2000);});
onUnmounted(()=>{disposed=true;generation++;contextGeneration++;clearInterval(timer);cancelAssetDialog();clearAssetPreferences();clearAssetsClient();unsubscribeArtifacts();unsubscribePreferences();unsubscribeUpload();unsubscribeNavigation?.();});
</script>
<template>
<main class="assets-page">
 <header><div><h1>{{tr('资产应用','Assets application')}}</h1><p class="app-status">{{context ? `${context.name} · ${tr('原生项目','Native project')} #${context.nativeProjectId}` : tr('等待可信项目绑定…','Waiting for trusted project binding…')}}</p><p class="app-status">{{tr('人工有效性、归属事实与执行授权互相独立。来源候选不代表当前可访问。','Manual validity, ownership facts and execution authorization are separate. Source candidates do not prove current accessibility.')}}</p></div><div><button class="button ghost" @click="setLocale(locale==='zh'?'en':'zh')">{{locale==='zh'?'English':'中文'}}</button><button class="button ghost" @click="client.close()">{{tr('关闭页面','Close page')}}</button></div></header>
 <p v-if="error" class="app-notice error" role="alert">{{error}}</p><p v-if="notice" class="app-notice" :class="{error:noticeKind==='error'}" role="status">{{notice}}</p>
 <template v-if="context"><nav aria-label="Assets views"><button v-for="tab in tabs" :key="tab[0]" :class="{active:view===tab[0]}" @click="view=tab[0]">{{tab[1]}}</button></nav>
 <AssetWorkspace :key="preferenceMount" v-if="view==='assets'" :projects="projects" :selected-project-id="context.nativeProjectId" :project-scope-only="true" :scanning-enabled="navigationState.handoff&&!navigationState.loading" @notify="notify" @changed="refresh" @reprobe="reprobe" />
 <QueryPanel v-else-if="view==='query'" :projects="projects" :profiles="profiles" :selected-project-id="context.nativeProjectId" :allow-create-project="false" @notify="notify" @started="view='tasks';refresh()" />
 <AssetRuleSettings v-else-if="view==='rules'" :projects="projects" @notify="notify" />
 <AssetOwnershipGate v-else-if="view==='ownership'" :projects="projects" :selected-project-id="context.nativeProjectId" @notify="notify" />
 <ExposureSurface v-else-if="view==='exposure'" :projects="projects" :selected-project-id="context.nativeProjectId" @notify="notify" />
 <ConfigurationProfiles v-else-if="view==='configuration'" @updated="refreshProfiles" />
 <section v-else class="panel"><header class="panel-heading"><h2>{{tabs.find(tab=>tab[0]===view)?.[1]}}</h2><button class="button secondary" :disabled="loading" @click="refresh">{{tr('刷新','Refresh')}}</button></header><p v-if="loading" class="read-state">{{tr('正在读取，本次数量尚未核实。','Reading; current counts have not been verified.')}}</p><p v-else-if="!loaded" class="read-state">{{tr('当前读数未知，不代表零条。','Current state is unknown; it is not an empty result.')}}</p>
 <div v-if="view==='tasks'" class="app-task-list"><article v-for="run in runs" :key="run.id"><header><h3>#{{run.id}} {{run.name}}</h3><p>{{run.status}} · {{run.pipeline}} · {{run.stage}} · {{run.processed}} / {{run.total}}</p></header><CollectionRunSummary :run="run"/><p v-if="run.error" class="app-notice error">{{run.error}}</p><div class="task-actions"><button v-if="run.status==='interrupted'" class="button secondary" :disabled="busy.has(run.id)" @click="runAction(run,'resume')">{{tr('继续同一任务','Resume same task')}}</button><button v-if="['queued','running','cancel_requested'].includes(run.status)" class="button secondary" :disabled="busy.has(run.id)||run.status==='cancel_requested'" @click="runAction(run,'cancel')">{{tr('请求取消','Request cancellation')}}</button></div></article><p v-if="loaded&&!runs.length&&!error">{{tr('本项目暂无资产任务。','No asset tasks in this project.')}}</p></div>
 <div v-else-if="view==='logs'" class="scroll"><table><thead><tr><th>{{tr('时间','Time')}}</th><th>{{tr('级别','Level')}}</th><th>{{tr('阶段','Stage')}}</th><th>{{tr('日志','Message')}}</th></tr></thead><tbody><tr v-for="row in logs" :key="row.id"><td>{{row.createdAt}}</td><td>{{row.level}}</td><td>{{row.stage}}</td><td>{{row.message}}</td></tr></tbody></table><p v-if="loaded&&!logs.length&&!error">{{tr('本项目暂无日志。','No logs in this project.')}}</p></div>
 <div v-else class="scroll"><table><thead><tr><th>{{tr('时间','Time')}}</th><th>{{tr('资产','Asset')}}</th><th>{{tr('变化','Change')}}</th><th>{{tr('说明','Summary')}}</th></tr></thead><tbody><tr v-for="row in events" :key="row.id"><td>{{row.createdAt}}</td><td>{{row.host}}</td><td>{{row.eventType}}</td><td>{{row.summary}}</td></tr></tbody></table><p v-if="loaded&&!events.length&&!error">{{tr('本项目暂无变化记录。','No asset changes in this project.')}}</p></div>
 </section></template><section v-else class="panel"><p>{{tr('页面不读取旧桌面数据库，也不猜测项目编号或默认配置。需要应用进程返回明确上下文。','This page does not open the desktop database, guess a project ID or invent default configuration. It requires explicit application context.')}}</p><button class="button secondary" @click="initialize">{{tr('重新读取应用上下文','Read application context again')}}</button></section>
 <section v-if="upload" class="panel asset-import-upload" aria-live="polite"><h2>{{tr('本次受控文档上传','Current controlled document upload')}}</h2><p>{{upload.phase}} · {{upload.uploadedBytes}} / {{upload.totalBytes}} {{tr('已确认传输字节','confirmed transfer bytes')}}</p><code>{{upload.uploadId||upload.operationId}}</code><p v-if="upload.resultRequiresReview" class="app-notice error">{{tr('上传或业务导入结果待核实，未自动重试或新建替代上传。先读取原生状态；这不等于导入未写入。','Upload or business-import outcome needs review. No automatic retry or replacement upload was created. Read native state first; this does not mean the import was not written.')}}</p><p v-if="upload.phase==='expired'">{{tr('接收中的临时上传已过期；没有继续或自动重放原导入。','The receiving upload expired. Its original import was not continued or replayed.')}}</p><p v-if="upload.phase==='completed'">{{tr('原导入已完成；暂存块是否仍保留不代表业务记录是否存在。','The original import completed. Retained staging chunks do not determine whether business records exist.')}}</p><p v-if="upload.errorCode"><code>{{upload.errorCode}}</code></p><div class="task-actions"><button v-if="upload.uploadId" class="button secondary" :disabled="uploadBusy" data-upload-action="check" @click="uploadAction('check')">{{tr('读取原生上传状态','Read native upload state')}}</button><button v-if="upload.phase==='receiving'" class="button secondary" :disabled="uploadBusy" data-upload-action="continue" @click="uploadAction('continue')">{{tr('继续接收并提交本次导入','Continue this upload and import')}}</button><button v-if="upload.phase==='receiving'" class="button ghost" :disabled="uploadBusy" data-upload-action="discard" @click="uploadAction('discard')">{{tr('丢弃接收中的临时上传','Discard receiving upload')}}</button></div></section>
 <p v-if="context&&!navigationState.handoff" class="app-status asset-navigation-status">{{navigationState.loading?tr('正在核对跨应用入口…','Checking application navigation…'):tr('发送到扫描需双方应用已安装启用，并在本项目授予 ui.handoff；当前不可用，未创建草稿或执行。','Sending to Scanning requires both apps installed and enabled with project ui.handoff grants. Currently unavailable; no draft or execution was created.')}}</p>
 <section v-if="artifacts.length" class="panel asset-export-downloads"><h2>{{tr('本页生成的导出文件','Exports issued in this page')}}</h2><article v-for="artifact in artifacts" :key="artifact.id"><span>{{artifact.kind}} · {{artifact.rows}} {{tr('条','rows')}} · {{artifact.id}}</span><button class="button secondary" :disabled="artifact.state==='starting'" @click="download(artifact.id)">{{artifact.state==='failed'?tr('重试取回文件','Retry download'):tr('下载文件','Download file')}}</button><small v-if="artifact.state==='started'">{{tr('已开始下载，不代表浏览器已保存。','Download started; browser save is not confirmed.')}}</small></article></section>
 <section v-if="context" class="asset-preferences-status" aria-live="polite"><p v-if="preferenceState.state==='saving'">{{tr('正在保存应用布局…','Saving application layout…')}}</p><p v-else-if="['unavailable','unsaved'].includes(preferenceState.state)">{{tr('布局尚未确认保存；本页更改不会自动覆盖远端较新的布局。筛选条件仅在本页会话保留。','Layout save is unconfirmed. Page changes will not automatically overwrite a newer saved layout. Filter queries stay in this page session.')}} <code>{{preferenceState.errorCode}}</code><button class="button ghost" @click="reloadPreferences">{{tr('重新读取已保存布局','Reload saved layout')}}</button></p><p v-else>{{tr('列顺序、列宽与调查模式保存在本应用；筛选条件仅在本页会话保留。','Column order, widths and investigation mode are saved in this application; filter queries stay in this page session.')}}</p></section>
</main>
</template>
